#!/usr/bin/env bash
# =============================================================================
# Regenerates the certificate fixtures used by the Java unit tests.
#
# These keys are TEST DATA: they are committed on purpose, trusted by nothing
# and valid for 100 years so the tests never start failing on a date.
# Never use them outside the test suites.
#
# Output (identical copies):
#   apps/test-client/src/test/resources/certs/
#   apps/spring-app/src/test/resources/certs/
# =============================================================================
set -Eeuo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
DAYS=36500
SUBJECT_BASE="/C=US/O=Example Corp/OU=Platform"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT
cd "$WORK"

ca() { # NAME CN
  openssl genpkey -algorithm EC -pkeyopt ec_paramgen_curve:prime256v1 -out "$1.key" 2>/dev/null
  cat >"$1.cnf" <<'EOF'
[req]
distinguished_name = dn
[dn]
[v3_ca]
basicConstraints = critical, CA:TRUE, pathlen:0
keyUsage = critical, keyCertSign, cRLSign
subjectKeyIdentifier = hash
EOF
  openssl req -x509 -new -key "$1.key" -sha256 -days "$DAYS" -subj "${SUBJECT_BASE}/CN=$2" \
    -config "$1.cnf" -extensions v3_ca -out "$1.crt"
}

leaf() { # NAME CN CA ALG EKU [SAN]
  local name=$1 cn=$2 issuer=$3 alg=$4 eku=$5 san=${6:-}
  if [[ "$alg" == "rsa" ]]; then
    openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 -out "${name}.key" 2>/dev/null
  else
    openssl genpkey -algorithm EC -pkeyopt ec_paramgen_curve:prime256v1 -out "${name}.key" 2>/dev/null
  fi
  {
    printf '[req]\ndistinguished_name = dn\n[dn]\n[v3_leaf]\n'
    printf 'basicConstraints = critical, CA:FALSE\nkeyUsage = critical, digitalSignature\n'
    if [[ "$eku" != "-" ]]; then printf 'extendedKeyUsage = %s\n' "$eku"; fi
    if [[ -n "$san" ]]; then printf 'subjectAltName = %s\n' "$san"; fi
  } >"${name}.cnf"
  openssl req -new -key "${name}.key" -subj "${SUBJECT_BASE}/CN=${cn}" -config "${name}.cnf" -out "${name}.csr"
  openssl x509 -req -in "${name}.csr" -CA "${issuer}.crt" -CAkey "${issuer}.key" \
    -set_serial "0x$(openssl rand -hex 16)" -days "$DAYS" -sha256 \
    -extfile "${name}.cnf" -extensions v3_leaf -out "${name}.crt" 2>/dev/null
}

ca ca "Test Root CA"
ca untrusted-ca "Untrusted Test CA"
leaf server localhost ca ec "serverAuth, clientAuth" "DNS:localhost, IP:127.0.0.1"
leaf client test-client ca ec "clientAuth"
leaf other-client intruder ca ec "clientAuth"
leaf server-only-usage server-only ca ec "serverAuth"
leaf untrusted-client test-client untrusted-ca ec "clientAuth"
leaf saml-sp saml-sp ca rsa "-"

# A SEC1 ("BEGIN EC PRIVATE KEY") copy to test the unsupported-format error.
openssl ec -in client.key -out client-sec1.key 2>/dev/null

for module in test-client spring-app; do
  dest="${ROOT}/apps/${module}/src/test/resources/certs"
  mkdir -p "$dest"
  rm -f "${dest}"/*.crt "${dest}"/*.key
  cp ca.crt untrusted-ca.crt server.crt server.key client.crt client.key other-client.crt other-client.key \
    server-only-usage.crt server-only-usage.key untrusted-client.crt untrusted-client.key \
    saml-sp.crt saml-sp.key client-sec1.key "$dest/"
  cat >"${dest}/README.md" <<'EOF'
# Test certificate fixtures

Generated by `tests/fixtures/generate-test-certs.sh`. These private keys are
public test data: valid for 100 years, trusted by nothing, and must never be
used outside the unit tests.
EOF
done
echo "Fixtures written to apps/*/src/test/resources/certs"
